import React from "react";

import template from "../../config/legal--template";
import LegalDocument from "../../modules/legal/LegalDocument";
import legalEnabled from "../../toggles/legal";
import privacyContent from "./privacy-content";
import termsContent from "./terms-content";

/**
 * The legal documents, configured.
 *
 * Two exports rather than one component taking a `document` prop, so each page
 * imports exactly the document it renders and neither pulls the other's copy
 * into its bundle. The structure and the styling are shared; only the words
 * differ, which is the correct place for the difference to live.
 */
export function TermsX() {
  if (!legalEnabled) return null;
  return <LegalDocument template={template} content={termsContent} />;
}

export function PrivacyX() {
  if (!legalEnabled) return null;
  return <LegalDocument template={template} content={privacyContent} />;
}

export default TermsX;
