import brand from "../../brand";

/**
 * Legal documents — design tokens.
 *
 * Terms and Privacy share this file because they are the same problem: a long
 * document somebody needs to be able to read. That is a typography exercise,
 * not a decorating one, so almost everything here is measure, leading and
 * spacing. There is no card, no shadow and no panel — the accent appears
 * exactly twice, on the eyebrow rule and on the current item in the contents.
 */

const color = {
  background: brand.colors.background,

  eyebrow: brand.colors.accent,
  rule: brand.colors.accent,
  title: brand.colors.primary,
  intro: brand.colors.textMuted,

  /* The placeholder notice. A tint of the accent rather than a warning colour:
     this is a note to the site owner, not an error. */
  noticeBackground: brand.colors.backgroundAlt,
  noticeBorder: brand.colors.border,
  noticeAccent: brand.colors.accent,
  noticeTitle: brand.colors.primary,
  noticeText: brand.colors.textMuted,

  tocTitle: brand.colors.primary,
  tocLink: brand.colors.textMuted,
  tocLinkHover: brand.colors.accent,
  tocBorder: brand.colors.border,

  sectionTitle: brand.colors.primary,
  body: brand.colors.textMuted,
  divider: brand.colors.border,
  strong: brand.colors.primary,

  link: brand.colors.primary,
  linkHover: brand.colors.accent,
  linkUnderline: brand.colors.border,

  focus: brand.colors.accent,
};

const layout = {
  /* Narrower than the site's usual 1280: a document does not get better by
     being as wide as the monitor it happens to be shown on. */
  /* 1152 rather than a round number: minus the 40px gutters that is exactly
     220 + 72 + 780, so the reading column actually reaches the measure the
     next token claims. At 1120 the grid asked for 32px more than existed and
     the document silently wrapped at 748px while its own heading wrapped at
     780px. */
  maxWidth: 1152,
  tocColumn: 220,
  /**
   * The reading measure. Around 72 characters at the body size, which is the
   * span the eye tracks without losing the line.
   */
  docColumn: 780,

  radius: 3,
  ruleWidth: 34,
  ruleHeight: 2,

  /** Below this the contents list stops being a sticky sidebar. */
  tocStackBelow: 1000,
  /** Below this the document loses its compact gutters. */
  compactBelow: 640,

  /** Clears the fixed header when a contents link jumps to a section. */
  scrollOffset: 110,
};

const spacing = {
  sectionTop: 88,
  sectionBottom: 104,
  sectionTopCompact: 56,
  sectionBottomCompact: 68,
  gutter: 40,
  gutterCompact: 20,

  columnGap: 72,
  columnGapCompact: 0,

  eyebrowGap: 18,
  titleGap: 20,
  introGap: 28,
  noticeGap: 44,
  noticePadding: 20,
  noticeTitleGap: 6,

  headGap: 8,

  tocTitleGap: 14,
  tocItemGap: 2,
  tocItemPaddingY: 7,
  tocStackGap: 40,

  docSectionGap: 44,
  docTitleGap: 16,
  docParagraphGap: 16,
  docListGap: 10,
};

const typography = {
  eyebrowFamily: brand.typography.body,
  eyebrowSize: 11,
  eyebrowWeight: brand.typography.weight.semibold,
  eyebrowTracking: brand.typography.tracking.wider,

  titleFamily: brand.typography.heading,
  titleSize: "clamp(30px, 3.4vw, 46px)",
  titleWeight: brand.typography.weight.heading,
  titleTracking: brand.typography.tracking.tight,
  titleLeading: 1.14,

  introFamily: brand.typography.body,
  introSize: "clamp(15px, 1.2vw, 17px)",
  introWeight: brand.typography.weight.regular,
  introLeading: 1.75,

  noticeTitleFamily: brand.typography.body,
  noticeTitleSize: 11,
  noticeTitleWeight: brand.typography.weight.semibold,
  noticeTitleTracking: "0.14em",
  noticeTextFamily: brand.typography.body,
  noticeTextSize: 13,
  noticeTextLeading: 1.7,

  tocTitleFamily: brand.typography.body,
  tocTitleSize: 11,
  tocTitleWeight: brand.typography.weight.semibold,
  tocTitleTracking: "0.14em",
  tocLinkFamily: brand.typography.body,
  tocLinkSize: 13,
  tocLinkWeight: brand.typography.weight.regular,
  tocLinkLeading: 1.5,

  sectionTitleFamily: brand.typography.heading,
  sectionTitleSize: "clamp(18px, 1.6vw, 22px)",
  sectionTitleWeight: brand.typography.weight.heading,
  sectionTitleTracking: "-0.02em",

  /* 16px and 1.8 leading. Legal copy is read slowly and in full, or it is not
     read at all — this is the one place on the site where comfort beats
     compactness. */
  bodyFamily: brand.typography.body,
  bodySize: 16,
  bodyWeight: brand.typography.weight.regular,
  bodyLeading: 1.8,
};

const timing = {
  hover: 420,
};

const template = { color, layout, spacing, timing, typography };

export default template;
