// Styling for the legal documents.
//
// Terms and Privacy are one design family and one stylesheet, because they are
// the same page with different words. What differs between them is content,
// which is exactly the thing a template should not own.
//
// The whole design is a reading measure, a heading hierarchy and a contents
// list. Nothing is boxed, nothing is shadowed, and the gold appears twice —
// the rule under the eyebrow and the hover state in the contents. A legal page
// that has been decorated is a legal page nobody finishes.

import template1 from "./template-1";

export type LegalTemplate = {
  css: string;
  rootClass: string;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-legal {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
}
.kr-legal__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
  display: grid;
  grid-template-columns: ${layout.tocColumn}px minmax(0, ${layout.docColumn}px);
  gap: ${spacing.columnGap}px;
  align-items: start;
}

/* The header spans both columns so the title is measured against the page
   rather than against the narrower reading column. */
.kr-legal__head {
  grid-column: 1 / -1;
  max-width: ${layout.docColumn}px;
  margin-bottom: ${spacing.headGap}px;
}

.kr-legal__eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 ${spacing.eyebrowGap}px;
  color: ${color.eyebrow};
  font-family: ${typography.eyebrowFamily};
  font-size: ${typography.eyebrowSize}px;
  font-weight: ${typography.eyebrowWeight};
  letter-spacing: ${typography.eyebrowTracking};
  text-transform: uppercase;
}
.kr-legal__eyebrow::before {
  content: "";
  width: ${layout.ruleWidth}px;
  height: ${layout.ruleHeight}px;
  flex-shrink: 0;
  background: ${color.rule};
}

.kr-legal__title {
  margin: 0 0 ${spacing.titleGap}px;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: ${typography.titleLeading};
}

.kr-legal__intro {
  margin: 0 0 ${spacing.introGap}px;
  color: ${color.intro};
  font-family: ${typography.introFamily};
  font-size: ${typography.introSize};
  font-weight: ${typography.introWeight};
  line-height: ${typography.introLeading};
}

.kr-legal__meta {
  margin: 0;
  color: ${color.intro};
  font-family: ${typography.noticeTextFamily};
  font-size: ${typography.noticeTextSize}px;
}

/* ── the placeholder notice ───────────────────────────────
   Deliberately visible. The wording below this is a template, not the client's
   approved legal copy, and a site that presents generated legal text as
   finished policy is making a claim on the client's behalf. Delete the
   notice field in the content file when the real document arrives and this
   whole block disappears with it. */
.kr-legal__notice {
  margin: ${spacing.introGap}px 0 0;
  padding: ${spacing.noticePadding}px;
  background: ${color.noticeBackground};
  border: 1px solid ${color.noticeBorder};
  border-left: 2px solid ${color.noticeAccent};
  border-radius: ${layout.radius}px;
}
.kr-legal__notice-title {
  margin: 0 0 ${spacing.noticeTitleGap}px;
  color: ${color.noticeTitle};
  font-family: ${typography.noticeTitleFamily};
  font-size: ${typography.noticeTitleSize}px;
  font-weight: ${typography.noticeTitleWeight};
  letter-spacing: ${typography.noticeTitleTracking};
  text-transform: uppercase;
}
.kr-legal__notice-text {
  margin: 0;
  color: ${color.noticeText};
  font-family: ${typography.noticeTextFamily};
  font-size: ${typography.noticeTextSize}px;
  line-height: ${typography.noticeTextLeading};
}

/* ── the contents ─────────────────────────────────────── */
.kr-legal__toc {
  position: sticky;
  /* Clears the fixed header, plus a little breathing room. */
  top: ${layout.scrollOffset}px;
  min-width: 0;
  padding-top: ${spacing.tocStackGap}px;
}
.kr-legal__toc-title {
  margin: 0 0 ${spacing.tocTitleGap}px;
  color: ${color.tocTitle};
  font-family: ${typography.tocTitleFamily};
  font-size: ${typography.tocTitleSize}px;
  font-weight: ${typography.tocTitleWeight};
  letter-spacing: ${typography.tocTitleTracking};
  text-transform: uppercase;
}
.kr-legal__toc-list {
  display: grid;
  gap: ${spacing.tocItemGap}px;
  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: kr-legal-toc;
}
.kr-legal__toc-link {
  display: block;
  padding: ${spacing.tocItemPaddingY}px 0;
  border-top: 1px solid ${color.tocBorder};
  color: ${color.tocLink};
  font-family: ${typography.tocLinkFamily};
  font-size: ${typography.tocLinkSize}px;
  font-weight: ${typography.tocLinkWeight};
  line-height: ${typography.tocLinkLeading};
  text-decoration: none;
  transition: color ${timing.hover}ms ${ease};
}
.kr-legal__toc-link:hover { color: ${color.tocLinkHover}; }
.kr-legal__toc-link:focus-visible {
  outline: 2px solid ${color.focus};
  outline-offset: 3px;
}

/* ── the document ─────────────────────────────────────── */
.kr-legal__doc { min-width: 0; }

.kr-legal__section {
  padding-top: ${spacing.tocStackGap}px;
  /* Anchored links land below the fixed header rather than under it. */
  scroll-margin-top: ${layout.scrollOffset}px;
}
.kr-legal__section + .kr-legal__section {
  margin-top: ${spacing.docSectionGap}px;
  border-top: 1px solid ${color.divider};
}

.kr-legal__section-title {
  margin: 0 0 ${spacing.docTitleGap}px;
  color: ${color.sectionTitle};
  font-family: ${typography.sectionTitleFamily};
  font-size: ${typography.sectionTitleSize};
  font-weight: ${typography.sectionTitleWeight};
  letter-spacing: ${typography.sectionTitleTracking};
}

.kr-legal__section p {
  margin: 0 0 ${spacing.docParagraphGap}px;
  color: ${color.body};
  font-family: ${typography.bodyFamily};
  font-size: ${typography.bodySize}px;
  font-weight: ${typography.bodyWeight};
  line-height: ${typography.bodyLeading};
}
.kr-legal__section p:last-child { margin-bottom: 0; }

.kr-legal__list {
  margin: 0 0 ${spacing.docParagraphGap}px;
  padding-left: 20px;
  display: grid;
  gap: ${spacing.docListGap}px;
}
.kr-legal__list li {
  color: ${color.body};
  font-family: ${typography.bodyFamily};
  font-size: ${typography.bodySize}px;
  line-height: ${typography.bodyLeading};
}
.kr-legal__list li::marker { color: ${color.rule}; }

.kr-legal__section a {
  color: ${color.link};
  text-decoration: underline;
  text-decoration-color: ${color.linkUnderline};
  text-underline-offset: 3px;
  transition: color ${timing.hover}ms ${ease},
    text-decoration-color ${timing.hover}ms ${ease};
}
.kr-legal__section a:hover {
  color: ${color.linkHover};
  text-decoration-color: ${color.linkHover};
}
.kr-legal__section a:focus-visible {
  outline: 2px solid ${color.focus};
  outline-offset: 3px;
}
.kr-legal__section strong { color: ${color.strong}; font-weight: 600; }

/* ── narrow screens ───────────────────────────────────────
   The contents list stops being a sidebar and becomes a short index at the top
   of the document, which is more useful on a phone than a sticky rail would be
   and costs one screenful rather than half the width. */
@media (max-width: ${layout.tocStackBelow}px) {
  .kr-legal__inner {
    grid-template-columns: minmax(0, 1fr);
    gap: ${spacing.columnGapCompact}px;
  }
  .kr-legal__toc {
    position: static;
    top: auto;
    padding-top: ${spacing.tocStackGap}px;
  }
  .kr-legal__toc-link {
    /* A comfortable tap target rather than a 13px line of text. */
    min-height: 44px;
    display: flex;
    align-items: center;
  }
}

@media (max-width: ${layout.compactBelow}px) {
  .kr-legal {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-legal__inner { padding: 0 ${spacing.gutterCompact}px; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-legal__toc-link,
  .kr-legal__section a { transition-duration: .01ms; }
}
`;

const template: LegalTemplate = {
  css,
  rootClass: "kr-legal",
};

export default template;
