import React from "react";

import type { LegalTemplate } from "../../templates/legal/default-template";
import type { LegalDocumentContent } from "./types";

export type LegalDocumentProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: LegalTemplate;
  content: LegalDocumentContent;
  enabled?: boolean;
};

/**
 * A legal document page.
 *
 * One component for both Terms and Privacy, because they are the same page
 * with different words. Everything it shows comes from `content`, including
 * the section numbering — the numbers are generated from position rather than
 * typed into each heading, so inserting a clause does not mean renumbering the
 * nine below it by hand.
 */
export default function LegalDocument({
  template,
  content,
  enabled = true,
}: LegalDocumentProps) {
  if (!enabled) return null;

  const root = template.rootClass;

  return (
    <section className={root} aria-labelledby="kr-legal-title">
      <style>{template.css}</style>

      <div className={`${root}__inner`}>
        <header className={`${root}__head`}>
          <p className={`${root}__eyebrow`}>{content.eyebrow}</p>

          <h1 className={`${root}__title`} id="kr-legal-title">
            {content.title}
          </h1>

          <p className={`${root}__intro`}>{content.intro}</p>

          {/* Only rendered when there is a real date to show. */}
          {content.updated ? (
            <p className={`${root}__meta`}>Last updated {content.updated}</p>
          ) : null}

          {content.notice ? (
            <aside className={`${root}__notice`}>
              <p className={`${root}__notice-title`}>{content.notice.title}</p>
              <p className={`${root}__notice-text`}>{content.notice.text}</p>
            </aside>
          ) : null}
        </header>

        <nav className={`${root}__toc`} aria-labelledby="kr-legal-toc-title">
          <p className={`${root}__toc-title`} id="kr-legal-toc-title">
            {content.tocTitle}
          </p>

          <ol className={`${root}__toc-list`}>
            {content.sections.map((section, index) => (
              <li key={section.id}>
                <a className={`${root}__toc-link`} href={`#${section.id}`}>
                  {index + 1}. {section.title}
                </a>
              </li>
            ))}
          </ol>
        </nav>

        <div className={`${root}__doc`}>
          {content.sections.map((section, index) => (
            <section
              key={section.id}
              className={`${root}__section`}
              id={section.id}
              aria-labelledby={`${section.id}-title`}
            >
              <h2 className={`${root}__section-title`} id={`${section.id}-title`}>
                {index + 1}. {section.title}
              </h2>

              {section.blocks.map((block, blockIndex) =>
                block.kind === "paragraph" ? (
                  <p key={`${section.id}-${blockIndex}`}>{block.text}</p>
                ) : (
                  <ul key={`${section.id}-${blockIndex}`} className={`${root}__list`}>
                    {block.items.map((item) => (
                      <li key={item}>{item}</li>
                    ))}
                  </ul>
                )
              )}
            </section>
          ))}
        </div>
      </div>
    </section>
  );
}
